import React, {
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import styled from 'styled-components';

import { Box } from '../Box';
import { Button } from '../Button';
import { Drop } from '../Drop';
import { InfiniteScroll } from '../InfiniteScroll';
import { Keyboard } from '../Keyboard';
import { FormContext } from '../Form/FormContext';
import { AnnounceContext } from '../../contexts';
import {
  isNodeAfterScroll,
  isNodeBeforeScroll,
  sizeStyle,
  useForwardedRef,
  useSizedIcon,
} from '../../utils';

import {
  StyledTextInput,
  StyledTextInputContainer,
  StyledPlaceholder,
  StyledIcon,
  StyledActionsGroup,
  StyledSuggestions,
} from './StyledTextInput';
import { MessageContext } from '../../contexts/MessageContext';
import { TextInputPropTypes } from './propTypes';
import { CopyButton } from './CopyButton';
import { useThemeValue } from '../../utils/useThemeValue';

const renderLabel = (suggestion) => {
  if (suggestion && typeof suggestion === 'object') {
    return suggestion.label || suggestion.value;
  }
  return suggestion;
};

const stringLabel = (suggestion) => {
  if (suggestion && typeof suggestion === 'object') {
    if (suggestion.label && typeof suggestion.label === 'string') {
      return suggestion.label;
    }
    return suggestion.value;
  }
  return suggestion;
};

const renderIcon = (iconValue, props) => {
  if (React.isValidElement(iconValue))
    return React.cloneElement(iconValue, props);

  const IconComponent = iconValue;
  return IconComponent ? <IconComponent {...props} /> : undefined;
};

const ContainerBox = styled(Box)`
  ${(props) =>
    props.dropHeight
      ? sizeStyle('max-height', props.dropHeight, props.theme)
      : 'max-height: inherit;'};
  /* IE11 hack to get drop contents to not overflow */
  @media screen and (-ms-high-contrast: active), (-ms-high-contrast: none) {
    width: 100%;
  }
`;

const StyledInlineActionButton = styled(Button)`
  padding-top: 0;
  padding-bottom: 0;
  ${(props) => props.$hidden && 'visibility: hidden;'}
`;

const isEmptyValue = (value) =>
  value === undefined || value === null || value === '';

const defaultDropAlign = { top: 'bottom', left: 'left' };

const TextInput = forwardRef(
  (
    {
      a11yTitle,
      clear,
      copy,
      defaultSuggestion,
      defaultValue,
      disabled,
      dropAlign = defaultDropAlign,
      dropHeight,
      dropProps,
      dropTarget,
      focusIndicator = true,
      icon,
      id,
      messages,
      name,
      onBlur,
      onChange,
      onClickCopy,
      onFocus,
      onKeyDown,
      onSelect,
      onSuggestionSelect,
      onSuggestionsClose,
      onSuggestionsOpen,
      password,
      placeholder,
      plain,
      readOnly: readOnlyProp,
      readOnlyCopy,
      reverse,
      suggestions,
      textAlign,
      type: typeProp,
      value: valueProp,
      width: widthProp,
      ...rest
    },
    ref,
  ) => {
    const { theme, passThemeFlag } = useThemeValue();
    const { format } = useContext(MessageContext);
    const announce = useContext(AnnounceContext);
    const formContext = useContext(FormContext);
    const inputRef = useForwardedRef(ref);
    const dropRef = useRef();
    const suggestionsRef = useRef();
    const readOnly = readOnlyProp || readOnlyCopy;
    // if this is a readOnly property, don't set a name with the form context
    // this allows Select to control the form context for the name.
    const [value, setValue] = formContext.useFormInput({
      name: readOnly ? undefined : name,
      value: valueProp,
    });

    const [focus, setFocus] = useState();
    const [showDrop, setShowDrop] = useState(false);
    const [passwordRevealed, setPasswordRevealed] = useState(false);
    // uncontrolled inputs outside a Form don't re-render on change, so track
    // emptiness here to toggle the clear button
    const [uncontrolledHasValue, setUncontrolledHasValue] = useState(
      () => !isEmptyValue(defaultValue),
    );

    const handleSuggestionSelect = useMemo(
      () => (onSelect && !onSuggestionSelect ? onSelect : onSuggestionSelect),
      [onSelect, onSuggestionSelect],
    );
    const handleTextSelect = useMemo(
      () => (onSelect && onSuggestionSelect ? onSelect : undefined),
      [onSelect, onSuggestionSelect],
    );

    const [suggestionsAtClose, setSuggestionsAtClose] = useState();

    const readOnlyCopyValidation = format({
      id: 'input.readOnlyCopy.validation',
      messages,
    });
    const readOnlyCopyPrompt = format({
      id: 'input.readOnlyCopy.prompt',
      messages,
    });

    const [tip, setTip] = useState(readOnlyCopyPrompt);
    const showPasswordMessage = format({
      id: 'textInput.showPassword',
      messages,
    });
    const hidePasswordMessage = format({
      id: 'textInput.hidePassword',
      messages,
    });
    const clearMessage = format({
      id: 'textInput.clear',
      messages,
    });

    const handleCopyClick = async (event) => {
      // uncontrolled inputs keep their current text on the DOM node, not
      // in `value`, which stays undefined outside a Form
      const currentValue = inputRef.current?.value ?? value ?? '';
      if (onClickCopy) await onClickCopy(event, currentValue);
      else await navigator.clipboard.writeText(currentValue);

      announce(readOnlyCopyValidation, 'assertive');
      setTip(readOnlyCopyValidation);
    };

    const onBlurCopy = () => {
      if (tip === readOnlyCopyValidation) setTip(readOnlyCopyPrompt);
    };

    const handleClearClick = () => {
      // Set the value natively so React emits onChange for controlled,
      // uncontrolled, and Form-managed inputs alike.
      const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
        window.HTMLInputElement.prototype,
        'value',
      ).set;
      nativeInputValueSetter.call(inputRef.current, '');
      inputRef.current.dispatchEvent(new Event('input', { bubbles: true }));
      // the clear button hides once the value is empty
      inputRef.current.focus();
    };

    const authoredType = typeProp || (password ? 'password' : undefined);
    const passwordToggle =
      password && authoredType === 'password' && !readOnlyCopy;

    useEffect(() => {
      // When the toggle stops applying, return the input to its authored type.
      if (!passwordToggle) setPasswordRevealed(false);
    }, [passwordToggle]);

    // form reset changes the value without firing onChange
    useEffect(() => {
      const form = clear ? inputRef.current?.form : undefined;
      if (!form) return undefined;
      let timer;
      const handleFormReset = () => {
        // reset fires before the browser restores field values
        timer = setTimeout(() =>
          setUncontrolledHasValue(!!inputRef.current?.value),
        );
      };
      form.addEventListener('reset', handleFormReset);
      return () => {
        clearTimeout(timer);
        form.removeEventListener('reset', handleFormReset);
      };
    }, [clear, inputRef]);

    const openDrop = useCallback(() => {
      setShowDrop(true);
      announce(
        format({
          id: 'textInput.suggestionIsOpen',
          messages,
        }),
      );
      announce(
        `${suggestions.length} ${format({
          id: 'textInput.suggestionsCount',
          messages,
        })}`,
      );
      if (onSuggestionsOpen) onSuggestionsOpen();
    }, [announce, messages, format, onSuggestionsOpen, suggestions]);

    const closeDrop = useCallback(() => {
      setSuggestionsAtClose(suggestions); // must be before closing drop
      setShowDrop(false);
      if (onSuggestionsClose) onSuggestionsClose();
    }, [onSuggestionsClose, suggestions]);

    const clickOutside = useCallback(
      (event) => {
        if (event.target !== inputRef.current) closeDrop();
      },
      [inputRef, closeDrop],
    );

    // Handle scenarios where we have focus, the drop isn't showing,
    // and the suggestions change. We don't want to open the drop if
    // the drop has been closed by onEsc and the suggestions haven't
    // changed. So, we remember the suggestions we are showing when
    // the drop was closed and only re-open it when the suggestions
    // subsequently change.
    useEffect(() => {
      if (
        focus &&
        !showDrop &&
        suggestions &&
        suggestions.length &&
        (!suggestionsAtClose ||
          suggestionsAtClose.length !== suggestions.length)
      ) {
        openDrop();
      }
    }, [focus, openDrop, showDrop, suggestions, suggestionsAtClose]);

    // if we have no suggestions, close drop if it's open
    useEffect(() => {
      if (showDrop && (!suggestions || !suggestions.length)) {
        closeDrop();
      }
    }, [closeDrop, showDrop, suggestions]);

    const valueSuggestionIndex = useMemo(
      () =>
        suggestions
          ? suggestions
              .map((suggestion) =>
                typeof suggestion === 'object' ? suggestion.value : suggestion,
              )
              .indexOf(value)
          : -1,
      [suggestions, value],
    );

    // choose the best suggestion, either the explicit default or the one
    // that matches the current value
    const resetSuggestionIndex = useMemo(() => {
      if (
        valueSuggestionIndex === -1 &&
        typeof defaultSuggestion === 'number'
      ) {
        return defaultSuggestion;
      }
      return valueSuggestionIndex;
    }, [defaultSuggestion, valueSuggestionIndex]);

    // activeSuggestionIndex unifies mouse and keyboard interaction of
    // the suggestions
    const [activeSuggestionIndex, setActiveSuggestionIndex] =
      useState(resetSuggestionIndex);

    // Only update active suggestion index when the mouse actually moves,
    // not when suggestions are moving under the mouse.
    const [mouseMovedSinceLastKey, setMouseMovedSinceLastKey] = useState();

    // set activeSuggestionIndex when value changes
    useEffect(
      () => setActiveSuggestionIndex(valueSuggestionIndex),
      [valueSuggestionIndex],
    );

    // reset activeSuggestionIndex when the drop is closed
    useEffect(() => {
      if (!showDrop) setActiveSuggestionIndex(resetSuggestionIndex);
    }, [resetSuggestionIndex, showDrop]);

    // announce active suggestion
    useEffect(() => {
      if (activeSuggestionIndex >= 0) {
        const label = stringLabel(suggestions[activeSuggestionIndex]);
        announce(
          `${label} ${format({
            id: 'textInput.enterSelect',
            messages,
          })}`,
        );
      }
    }, [activeSuggestionIndex, announce, messages, format, suggestions]);

    // make sure activeSuggestion is visible in scroll
    useEffect(() => {
      const timer = setTimeout(() => {
        const list = suggestionsRef.current;
        if (showDrop && activeSuggestionIndex !== -1 && list) {
          const container = list.parentNode;
          const item = list.children[activeSuggestionIndex];
          if (container.scrollTo) {
            if (isNodeAfterScroll(item, container))
              container.scrollTo(
                0,
                item.offsetTop -
                  (container.getBoundingClientRect().height -
                    item.getBoundingClientRect().height),
              );
            else if (isNodeBeforeScroll(item, container))
              container.scrollTo(0, item.offsetTop);
          }
        }
      }, 50); // delay to allow Drop to animate in
      return () => clearTimeout(timer);
    }, [activeSuggestionIndex, showDrop]);

    useEffect(() => {
      if (readOnly && inputRef?.current && inputRef.current.scrollLeft > 0) {
        inputRef.current.scrollLeft = 0;
      }
    }, [readOnly, inputRef, inputRef?.current?.scrollLeft]);

    const setValueFromSuggestion = (event, suggestion) => {
      // if we stole the focus in the drop, perhaps by interacting with
      // a suggestion button or the scrollbar, give it back
      inputRef.current.focus();
      inputRef.current.value = suggestion; // needed for uncontrolled cases
      closeDrop();
      if (handleSuggestionSelect) {
        if (event.persist) event.persist();
        const adjustedEvent = event;
        adjustedEvent.suggestion = suggestion;
        handleSuggestionSelect(adjustedEvent);
      }
      setValue(suggestion);

      if (clear) {
        setUncontrolledHasValue(!isEmptyValue(suggestion));
      }
    };

    const onNextSuggestion = useCallback(
      (event) => {
        event.preventDefault();
        const nextActiveIndex = Math.min(
          activeSuggestionIndex + 1,
          suggestions.length - 1,
        );
        setActiveSuggestionIndex(nextActiveIndex);
        setMouseMovedSinceLastKey(false);
      },
      [activeSuggestionIndex, suggestions],
    );

    const onPreviousSuggestion = useCallback(
      (event) => {
        event.preventDefault();
        const nextActiveIndex = Math.max(activeSuggestionIndex - 1, 0);
        setActiveSuggestionIndex(nextActiveIndex);
        setMouseMovedSinceLastKey(false);
      },
      [activeSuggestionIndex],
    );

    // account for input value in both controlled and uncontrolled scenarios
    const hasValue = value || inputRef.current?.value;
    const showStyledPlaceholder = useMemo(
      () => placeholder && typeof placeholder !== 'string' && !hasValue,
      [hasValue, placeholder],
    );

    let drop;
    const extraProps = {
      onSelect: handleTextSelect,
    };

    if (showDrop) {
      drop = (
        <Drop
          ref={dropRef}
          id={id ? `text-input-drop__${id}` : undefined}
          align={dropAlign}
          responsive={false}
          target={dropTarget || inputRef.current}
          onClickOutside={clickOutside}
          onEsc={closeDrop}
          // TextInput manages its own keyboard behavior via keyboardProps
          trapFocus={false}
          {...dropProps}
        >
          <ContainerBox
            id={id ? `listbox__${id}` : undefined}
            role="listbox"
            overflow="auto"
            dropHeight={dropHeight}
            onMouseMove={() => setMouseMovedSinceLastKey(true)}
            {...passThemeFlag}
          >
            <StyledSuggestions ref={suggestionsRef} {...passThemeFlag}>
              <InfiniteScroll
                items={suggestions}
                step={theme.select.step}
                show={
                  activeSuggestionIndex !== -1
                    ? activeSuggestionIndex
                    : undefined
                }
              >
                {(suggestion, index, itemRef) => {
                  const active = activeSuggestionIndex === index;
                  const selected = suggestion === value;
                  // Determine whether the label is done as a child or
                  // as an option Button kind property.
                  const renderedLabel = renderLabel(suggestion);
                  let child;
                  if (typeof renderedLabel !== 'string')
                    // must be an element rendered by suggestions.label
                    child = renderedLabel;
                  else if (!theme.button.option)
                    // don't have theme support, need to layout here
                    /*
                    Not adding a theme object now because this code path
                    is not used in the HPE theme, but we may add theme
                    support here in the future.
                    */
                    child = (
                      <Box align="start" pad="small">
                        {renderedLabel}
                      </Box>
                    );
                  // if we have a child, turn on plain

                  return (
                    <li
                      key={`${stringLabel(suggestion)}-${index}`}
                      ref={itemRef}
                    >
                      <Button
                        id={id ? `listbox-option-${index}__${id}` : undefined}
                        role="option"
                        aria-selected={selected ? 'true' : 'false'}
                        active={active}
                        fill="horizontal"
                        plain={!child ? undefined : true}
                        align="start"
                        kind={!child ? 'option' : undefined}
                        label={!child ? renderedLabel : undefined}
                        onClick={(event) =>
                          setValueFromSuggestion(event, suggestion)
                        }
                        onMouseMove={
                          mouseMovedSinceLastKey &&
                          activeSuggestionIndex !== index
                            ? () => setActiveSuggestionIndex(index)
                            : undefined
                        }
                        keyboard={!mouseMovedSinceLastKey}
                      >
                        {child}
                      </Button>
                    </li>
                  );
                }}
              </InfiniteScroll>
            </StyledSuggestions>
          </ContainerBox>
        </Drop>
      );
    }

    const keyboardProps = { onKeyDown };
    if (showDrop) {
      keyboardProps.onEnter = (event) => {
        // prevent submitting forms via Enter when the drop is open
        event.preventDefault();
        if (activeSuggestionIndex >= 0)
          setValueFromSuggestion(event, suggestions[activeSuggestionIndex]);
        else closeDrop();
      };
      if (activeSuggestionIndex > 0) keyboardProps.onUp = onPreviousSuggestion;
      if (activeSuggestionIndex < suggestions.length - 1)
        keyboardProps.onDown = onNextSuggestion;
      keyboardProps.onTab = closeDrop;
    } else if (suggestions && suggestions.length > 0) {
      keyboardProps.onDown = openDrop;
    }

    /*
    If the text input has a list of suggestions, add the WAI-ARIA 1.2
    combobox role and states.
    */
    let comboboxProps = {};
    let activeOptionID;
    if (id && suggestions?.length > -1) {
      if (showDrop && activeSuggestionIndex > -1) {
        activeOptionID = `listbox-option-${activeSuggestionIndex}__${id}`;
      }
      comboboxProps = {
        'aria-activedescendant': activeOptionID,
        'aria-autocomplete': 'list',
        'aria-expanded': showDrop ? 'true' : 'false',
        'aria-controls': showDrop ? `listbox__${id}` : undefined,
        role: 'combobox',
      };
    }
    // For the Keyboard target below, if we have focus,
    // either on the input element or within the drop,
    // then we set the target to the document,
    // otherwise we only listen to onDown on the input element itself,
    // primarily for tests.

    const textInputIcon = useSizedIcon(icon, rest.size, theme);
    const showPasswordIcon = theme.textInput?.icons?.showPassword;
    const hidePasswordIcon = theme.textInput?.icons?.hidePassword;
    const clearIcon = theme.textInput?.icons?.clear;
    let inputType = authoredType;
    if (passwordToggle) {
      inputType = passwordRevealed ? 'text' : 'password';
    }
    const showTextInputIcon = !!textInputIcon && !readOnlyCopy;

    const copyButtonElement = (
      <CopyButton
        authoredType={authoredType}
        disabled={disabled}
        messages={messages}
        onBlurCopy={onBlurCopy}
        onCopy={handleCopyClick}
        tip={tip}
        value={value}
      />
    );

    const clearable = clear && !readOnly;
    const hasClearableValue =
      value !== undefined && value !== null
        ? value !== ''
        : uncontrolledHasValue;

    const clearButton = clearable ? (
      <StyledInlineActionButton
        disabled={disabled}
        kind="toolbar"
        icon={renderIcon(clearIcon, { 'aria-hidden': true })}
        onClick={handleClearClick}
        aria-label={clearMessage}
        // keep the slot while empty so the input width doesn't shift
        $hidden={!hasClearableValue}
        {...passThemeFlag}
      />
    ) : undefined;

    const passwordToggleButton = passwordToggle ? (
      <StyledInlineActionButton
        disabled={disabled}
        kind="toolbar"
        icon={
          passwordRevealed
            ? renderIcon(hidePasswordIcon, { 'aria-hidden': true })
            : renderIcon(showPasswordIcon, { 'aria-hidden': true })
        }
        onClick={() => setPasswordRevealed((current) => !current)}
        aria-label={
          passwordRevealed ? hidePasswordMessage : showPasswordMessage
        }
        {...passThemeFlag}
      />
    ) : undefined;

    const copyButton = readOnlyCopy || copy ? copyButtonElement : undefined;
    // Order: clear sits next to the text, then password visibility, then the
    // non-destructive copy action.
    const actionsGroup =
      clearButton || passwordToggleButton || copyButton ? (
        <StyledActionsGroup {...passThemeFlag}>
          {clearButton}
          {passwordToggleButton}
          {copyButton}
        </StyledActionsGroup>
      ) : undefined;
    const hasActionsGroup = !!actionsGroup;
    const iconOnRight = reverse;
    const showLeadingIcon = showTextInputIcon && !iconOnRight;
    const showTrailingIcon = showTextInputIcon && iconOnRight;

    return (
      <StyledTextInputContainer
        hasButton={!!actionsGroup}
        readOnlyProp={readOnly} // readOnlyProp to avoid passing to DOM
        readOnlyCopy={readOnlyCopy}
        plain={plain}
        border={!plain}
        widthProp={widthProp}
        onMouseMove={() => setMouseMovedSinceLastKey(true)}
        {...passThemeFlag}
      >
        {/* reverse changes the icon position; actions always stay on the */}
        {/* right. */}
        {showStyledPlaceholder && (
          <StyledPlaceholder {...passThemeFlag}>
            {placeholder}
          </StyledPlaceholder>
        )}
        {showLeadingIcon && (
          <StyledIcon
            reverse={iconOnRight}
            hasActionsGroup={hasActionsGroup}
            theme={theme}
          >
            {textInputIcon}
          </StyledIcon>
        )}
        <Keyboard target={focus ? 'document' : undefined} {...keyboardProps}>
          <StyledTextInput
            aria-label={a11yTitle}
            ref={inputRef}
            id={id}
            name={name}
            autoComplete="off"
            disabled={disabled}
            plain={plain}
            placeholder={
              typeof placeholder === 'string' ? placeholder : undefined
            }
            icon={showTextInputIcon && !hasActionsGroup ? icon : undefined}
            reverse={iconOnRight}
            focus={focus}
            hasButton={hasActionsGroup}
            hasActionsGroup={hasActionsGroup}
            hasClear={clearable}
            hasLeadingIcon={showLeadingIcon}
            hasTrailingIcon={showTrailingIcon}
            focusIndicator={focusIndicator}
            textAlign={textAlign}
            type={inputType}
            widthProp={widthProp}
            {...passThemeFlag}
            {...rest}
            {...extraProps}
            {...comboboxProps}
            defaultValue={renderLabel(defaultValue)}
            value={renderLabel(value)}
            readOnly={readOnly}
            readOnlyCopy={readOnlyCopy}
            onFocus={(event) => {
              // Don't do anything if we are acting like we already have
              // focus. This can happen when this input loses focus temporarily
              // to our drop, see onBlur() handler below.
              if (!focus) {
                setFocus(true);
                if (suggestions && suggestions.length > 0) {
                  announce(
                    format({
                      id: 'textInput.suggestionsExist',
                      messages,
                    }),
                  );
                  openDrop();
                }
                if (onFocus) onFocus(event);
              }
            }}
            onBlur={(event) => {
              // Only treat it as a blur if the element receiving focus
              // isn't in our drop. The relatedTarget will be our drop
              // when the user clicks on a suggestion or interacts with the
              // scrollbar in the drop.
              if (
                !event.relatedTarget ||
                event.relatedTarget !== dropRef.current
              ) {
                setFocus(false);
                if (onBlur) onBlur(event);
              }
            }}
            onChange={
              readOnly
                ? undefined
                : (event) => {
                    // when TextInput is not contained in a Form, no re-render
                    // will come from this onChange and remove the placeholder
                    // so we need to update state to ensure the styled
                    // placeholder only appears when there is no value
                    if (suggestions && focus && !showDrop) {
                      openDrop();
                    }
                    setValue(event.target.value);
                    if (clear) {
                      setUncontrolledHasValue(!!event.target.value);
                    }
                    setActiveSuggestionIndex(resetSuggestionIndex);
                    if (onChange) onChange(event);
                  }
            }
          />
        </Keyboard>
        {actionsGroup}
        {showTrailingIcon && (
          <StyledIcon
            reverse={iconOnRight}
            hasActionsGroup={hasActionsGroup}
            theme={theme}
          >
            {textInputIcon}
          </StyledIcon>
        )}
        {!readOnly && drop}
      </StyledTextInputContainer>
    );
  },
);

TextInput.displayName = 'TextInput';
TextInput.propTypes = TextInputPropTypes;

export { TextInput };
